from pathlib import Path
import re
p=Path('index.html')
s=p.read_text()

s=s.replace('LAME — Howie Lucas Pinball v34','LAME — Howie Lucas Pinball v35',1)

helpers=r'''function chromeGrad(x1,y1,x2,y2){const g=ctx.createLinearGradient(x1,y1,x2,y2);g.addColorStop(0,"#4f5962");g.addColorStop(.18,"#f7fbff");g.addColorStop(.42,"#8c969f");g.addColorStop(.62,"#ffffff");g.addColorStop(1,"#3b434a");return g}function drawRealBumper(b){const flash=b.flash>0;ctx.save();ctx.shadowBlur=flash?30:12;ctx.shadowColor=flash?"#fff2a8":"#49b8ff55";ctx.beginPath();ctx.arc(b.x,b.y,b.r+6,0,Math.PI*2);ctx.fillStyle=chromeGrad(b.x-b.r,b.y-b.r,b.x+b.r,b.y+b.r);ctx.fill();ctx.strokeStyle="#181b1e";ctx.lineWidth=3;ctx.stroke();const dg=ctx.createRadialGradient(b.x-12,b.y-15,4,b.x,b.y,b.r);dg.addColorStop(0,flash?"#fffef0":"#d9f6ff");dg.addColorStop(.25,flash?"#ffe45d":"#2f9dcc");dg.addColorStop(.72,"#0b2735");dg.addColorStop(1,"#020608");ctx.beginPath();ctx.arc(b.x,b.y,b.r-5,0,Math.PI*2);ctx.fillStyle=dg;ctx.fill();ctx.strokeStyle="#d7e0e6";ctx.lineWidth=2;ctx.stroke();ctx.beginPath();ctx.arc(b.x,b.y,b.r*.48,0,Math.PI*2);ctx.strokeStyle=flash?"#fff":"#ffd21f";ctx.lineWidth=4;ctx.stroke();ctx.fillStyle="#fff";ctx.font="900 14px Arial";ctx.textAlign="center";ctx.shadowBlur=6;ctx.shadowColor="#000";ctx.fillText(b.label,b.x,b.y+5);ctx.restore();b.flash=Math.max(0,b.flash-1)}function drawRealPost(p){ctx.save();ctx.shadowBlur=8;ctx.shadowColor="#000";ctx.beginPath();ctx.arc(p.x,p.y,p.r+4,0,Math.PI*2);ctx.fillStyle=chromeGrad(p.x-p.r,p.y-p.r,p.x+p.r,p.y+p.r);ctx.fill();ctx.strokeStyle="#202428";ctx.lineWidth=2;ctx.stroke();ctx.beginPath();ctx.arc(p.x-4,p.y-5,p.r*.42,0,Math.PI*2);ctx.fillStyle="#f6f8fa";ctx.fill();ctx.restore()}function drawRealBox(bx,by,bw,bh){const lit=boxLit;ctx.save();ctx.shadowBlur=lit?32:15;ctx.shadowColor=lit?"#ffe66d":"#000";const g=ctx.createLinearGradient(bx,by,bx+bw,by+bh);g.addColorStop(0,lit?"#d69a55":"#a96b34");g.addColorStop(.48,lit?"#b77531":"#7c461f");g.addColorStop(1,lit?"#e4ad68":"#5f3216");ctx.fillStyle=g;ctx.strokeStyle=lit?"#fff2a3":"#d7a368";ctx.lineWidth=lit?7:4;ctx.fillRect(bx,by,bw,bh);ctx.strokeRect(bx,by,bw,bh);ctx.globalAlpha=.22;ctx.strokeStyle="#2d1609";ctx.lineWidth=2;for(let yy=by+12;yy<by+bh;yy+=16){ctx.beginPath();ctx.moveTo(bx+5,yy);ctx.lineTo(bx+bw-5,yy+4);ctx.stroke()}ctx.globalAlpha=1;ctx.strokeStyle="#4c2b16";ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(bx+bw/2,by);ctx.lineTo(bx+bw/2,by+bh);ctx.stroke();ctx.shadowBlur=lit?24:4;ctx.fillStyle=lit?"#fff36a":"#19100a";ctx.font="900 44px Impact";ctx.textAlign="center";ctx.fillText("LAME",bx+bw/2,by+92);ctx.shadowBlur=0;for(let i=0;i<4;i++){const fx=bx+i*52+2,open=i<boxOpen;ctx.save();ctx.translate(fx+24,by);if(open)ctx.rotate((i<2?-1:1)*.8);const fg=ctx.createLinearGradient(-24,-34,24,0);fg.addColorStop(0,"#d59a55");fg.addColorStop(1,"#7a431d");ctx.fillStyle=fg;ctx.strokeStyle="#4d2a14";ctx.lineWidth=2;ctx.fillRect(-24,-34,48,34);ctx.strokeRect(-24,-34,48,34);ctx.restore()}ctx.restore()}function drawRealFlipper(side,held){const f=flipper(side,held);ctx.save();ctx.lineCap="round";ctx.shadowBlur=12;ctx.shadowColor=held?"#ffd21f88":"#000";ctx.strokeStyle="#202428";ctx.lineWidth=38;ctx.beginPath();ctx.moveTo(f.pivot.x,f.pivot.y);ctx.lineTo(f.tip.x,f.tip.y);ctx.stroke();ctx.strokeStyle=chromeGrad(f.pivot.x,f.pivot.y-18,f.tip.x,f.tip.y+18);ctx.lineWidth=30;ctx.beginPath();ctx.moveTo(f.pivot.x,f.pivot.y);ctx.lineTo(f.tip.x,f.tip.y);ctx.stroke();ctx.strokeStyle=held?"#ffd21f":"#b91313";ctx.lineWidth=8;ctx.beginPath();ctx.moveTo(f.pivot.x,f.pivot.y);ctx.lineTo(f.tip.x,f.tip.y);ctx.stroke();ctx.beginPath();ctx.arc(f.pivot.x,f.pivot.y,20,0,Math.PI*2);ctx.fillStyle=chromeGrad(f.pivot.x-20,f.pivot.y-20,f.pivot.x+20,f.pivot.y+20);ctx.fill();ctx.strokeStyle="#111";ctx.lineWidth=2;ctx.stroke();ctx.restore()}function drawLauncherAssembly(){ctx.save();ctx.shadowBlur=8;ctx.shadowColor="#000";ctx.strokeStyle="#dfe7ec";ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(536,1160);ctx.lineTo(536,1242);ctx.stroke();ctx.strokeStyle="#9ba7af";ctx.lineWidth=4;ctx.beginPath();for(let y=1166;y<=1232;y+=8){ctx.moveTo(518,y);ctx.lineTo(554,y+4);ctx.lineTo(518,y+8)}ctx.stroke();const pg=ctx.createLinearGradient(505,1238,566,1238);pg.addColorStop(0,"#333");pg.addColorStop(.25,"#f5f7f8");pg.addColorStop(.55,"#777");pg.addColorStop(1,"#222");ctx.fillStyle=pg;ctx.fillRect(505,1238,62,18);ctx.strokeStyle="#0f0f0f";ctx.lineWidth=2;ctx.strokeRect(505,1238,62,18);ctx.fillStyle="#b91313";ctx.fillRect(526,1256,20,34);ctx.restore()}function drawRealBall(){ctx.save();ctx.shadowBlur=12;ctx.shadowColor="#000";ctx.beginPath();ctx.arc(ball.x,ball.y,ball.r+1,0,Math.PI*2);const g=ctx.createRadialGradient(ball.x-5,ball.y-6,1,ball.x+2,ball.y+3,ball.r+2);g.addColorStop(0,"#ffffff");g.addColorStop(.18,"#e9eef2");g.addColorStop(.42,"#9ca7af");g.addColorStop(.72,"#4f5961");g.addColorStop(1,"#111417");ctx.fillStyle=g;ctx.fill();ctx.strokeStyle="#d6dde2";ctx.lineWidth=1.5;ctx.stroke();ctx.beginPath();ctx.arc(ball.x-4,ball.y-5,3,0,Math.PI*2);ctx.fillStyle="rgba(255,255,255,.8)";ctx.fill();ctx.restore()}'''

if 'function chromeGrad(' not in s:
    s=s.replace('function drawWorld(){',helpers+'function drawWorld(){',1)

# darker, lacquered playfield while preserving black look
s=s.replace('ctx.fillStyle="#000";ctx.fillRect(0,0,W,WORLD_H);','const pf=ctx.createLinearGradient(0,0,W,WORLD_H);pf.addColorStop(0,"#101317");pf.addColorStop(.32,"#020304");pf.addColorStop(.7,"#0b0d10");pf.addColorStop(1,"#000");ctx.fillStyle=pf;ctx.fillRect(0,0,W,WORLD_H);ctx.save();ctx.globalAlpha=.08;ctx.strokeStyle="#fff";for(let x=30;x<W;x+=55){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x-120,WORLD_H);ctx.stroke()}ctx.restore();',1)

# realistic bumpers
s=re.sub(r'bumpers\.forEach\(\(b,i\)=>\{.*?b\.flash=Math\.max\(0,b\.flash-1\);ctx\.fillStyle="#fff";ctx\.font="900 15px Arial";ctx\.fillText\(b\.label,b\.x,b\.y\+5\)\}\);','bumpers.forEach(drawRealBumper);',s,count=1)

# realistic box
s=re.sub(r'ctx\.save\(\);const lit=boxLit;if\(lit\)\{ctx\.shadowBlur=30;.*?ctx\.restore\(\);for\(let i=0;i<4;i\+\+\)\{.*?ctx\.restore\(\)\}','drawRealBox(bx,by,bw,bh)',s,count=1)

# realistic posts
s=re.sub(r'posts\.forEach\(p=>\{ctx\.beginPath\(\);ctx\.arc\(p\.x,p\.y,p\.r,0,Math\.PI\*2\);ctx\.fillStyle="#ddd";ctx\.fill\(\);ctx\.strokeStyle="#333";ctx\.lineWidth=3;ctx\.stroke\(\)\}\);','posts.forEach(drawRealPost);',s,count=1)

# realistic flippers
s=re.sub(r'\[\["L",left\],\["R",right\]\]\.forEach\(\(\[s,h\]\)=>\{const f=flipper\(s,h\);ctx\.strokeStyle=h\?"#ffd12c":"#f1f1f1";ctx\.lineWidth=30;ctx\.lineCap="round";ctx\.beginPath\(\);ctx\.moveTo\(f\.pivot\.x,f\.pivot\.y\);ctx\.lineTo\(f\.tip\.x,f\.tip\.y\);ctx\.stroke\(\)\}\);ctx\.lineCap="butt";','drawRealFlipper("L",left);drawRealFlipper("R",right);ctx.lineCap="butt";',s,count=1)

# realistic ball
s=re.sub(r'ctx\.beginPath\(\);ctx\.arc\(ball\.x,ball\.y,ball\.r,0,Math\.PI\*2\);const g=ctx\.createRadialGradient\(ball\.x-4,ball\.y-4,2,ball\.x,ball\.y,13\);g\.addColorStop\(0,"#fff"\);g\.addColorStop\(1,"#666"\);ctx\.fillStyle=g;ctx\.fill\(\);ctx\.strokeStyle="#111";ctx\.lineWidth=2;ctx\.stroke\(\)','drawRealBall()',s,count=1)

# add visible spring/plunger in shooter lane
s=s.replace('ctx.strokeRect(500,130,72,1075);ctx.save();','ctx.strokeRect(500,130,72,1075);drawLauncherAssembly();ctx.save();',1)

# chrome up the top launch/guide rails visually
s=s.replace('ctx.strokeStyle="#e7b400";ctx.lineWidth=8;ctx.beginPath();ctx.moveTo(24,165);ctx.lineTo(120,88);ctx.lineTo(480,88);ctx.lineTo(500,135);ctx.stroke();','ctx.shadowBlur=8;ctx.shadowColor="#000";ctx.strokeStyle="#181b1e";ctx.lineWidth=14;ctx.beginPath();ctx.moveTo(24,165);ctx.lineTo(120,88);ctx.lineTo(480,88);ctx.lineTo(500,135);ctx.stroke();ctx.strokeStyle=chromeGrad(24,88,500,165);ctx.lineWidth=8;ctx.beginPath();ctx.moveTo(24,165);ctx.lineTo(120,88);ctx.lineTo(480,88);ctx.lineTo(500,135);ctx.stroke();ctx.shadowBlur=0;',1)

p.write_text(s)
print('v35 patched: realistic table visuals, chrome bumpers/flippers/ball, 3D box, launcher spring')
